    extra={'C1':' (고리뼈)','C2':' (중쇠뼈)','C7':' (솟을뼈)'}.get(c,'')
    a('vname_'+c,'제%s%s%s · %s'%(c[1:],n,extra,c),'','%s vertebra %s'%(e,c[1:]),'b','')

